func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	if t.colors == nil {
		return DefaultTheme().Color(name, variant)
	}

	if variants, ok := t.colors[name]; ok {
		if c, ok := variants[variant]; ok {
			return c
		}
	}

	return DefaultTheme().Color(name, variant)
}

// Font returns the font resource for the given text style
// JSON themes fall back to the default theme for fonts
func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	return DefaultTheme().Font(style)
}

// Icon returns the icon resource for the given icon name
// JSON themes fall back to the default theme for icons
func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	return DefaultTheme().Icon(name)
}

// Size returns the size for the given size name
func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if t.sizes == nil {
		return DefaultTheme().Size(name)
	}

	if size, ok := t.sizes[name]; ok {
		return size
	}

	return DefaultTheme().Size(name)
}

// jsonThemeData represents the JSON structure for theme data
type jsonThemeData struct {
	Colors map[string]map[string]string `json:"colors"` // colorName -> variant -> hex color
	Sizes  map[string]float32           `json:"sizes"`  // sizeName -> value
}

// FromJSON creates a Theme from JSON data.
// The JSON should contain "colors" and "sizes" maps.
// Colors are specified as hex strings (e.g., "#FF0000") organized by color name and variant.
// Sizes are specified as float32 values.
//
// Example JSON:
//   {
//     "colors": {
//       "primary": {
//         "light": "#007AFF",
//         "dark": "#0A84FF"
//       }
//     },
//     "sizes": {
//       "text": 14.0,
//       "padding": 4.0
//     }
//   }
//
// Since: 2.5
func FromJSON(data []byte) (fyne.Theme, error) {
	var themeData jsonThemeData
	if err := json.Unmarshal(data, &themeData); err != nil {
		return nil, err
	}

	theme := &jsonTheme{
		colors: make(map[fyne.ThemeColorName]map[fyne.ThemeVariant]color.Color),
		sizes:  make(map[fyne.ThemeSizeName]float32),
	}

	// Parse colors
	for colorName, variants := range themeData.Colors {
		theme.colors[fyne.ThemeColorName(colorName)] = make(map[fyne.ThemeVariant]color.Color)
		for variantName, hexColor := range variants {
			if c, err := parseHexColor(hexColor); err == nil {
				theme.colors[fyne.ThemeColorName(colorName)][fyne.ThemeVariant(variantName)] = c
			}
		}
	}

	// Parse sizes
	for sizeName, sizeValue := range themeData.Sizes {
		theme.sizes[fyne.ThemeSizeName(sizeName)] = sizeValue
	}

	return theme, nil
}

// parseHexColor converts a hex color string to color.Color
func parseHexColor(hex string) (color.Color, error) {
	var r, g, b, a uint8 = 0, 0, 0, 255

	if len(hex) > 0 && hex[0] == '#' {
		hex = hex[1:]
	}

	switch len(hex) {
	case 6:
		_, err := parseRGB(hex, &r, &g, &b)
		if err != nil {
			return nil, err
		}
	case 8:
		_, err := parseRGBA(hex, &r, &g, &b, &a)
		if err != nil {
			return nil, err
		}
	default:
		return nil, &json.UnsupportedValueError{}
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

// parseRGB parses RGB hex values
func parseRGB(hex string, r, g, b *uint8) (int, error) {
	var err error
	*r, err = parseHexByte(hex[0:2])
	if err != nil {
		return 0, err
	}
	*g, err = parseHexByte(hex[2:4])
	if err != nil {
		return 0, err
	}
	*b, err = parseHexByte(hex[4:6])
	if err != nil {
		return 0, err
	}
	return 6, nil
}

// parseRGBA parses RGBA hex values
func parseRGBA(hex string, r, g, b, a *uint8) (int, error) {
	n, err := parseRGB(hex, r, g, b)
	if err != nil {
		return n, err
	}
	*a, err = parseHexByte(hex[6:8])
	if err != nil {
		return 6, err
	}
	return 8, nil
}

// parseHexByte converts a 2-character hex string to a byte
func parseHexByte(hex string) (uint8, error) {
	var val uint8
	for i := 0; i < 2; i++ {
		c := hex[i]
		val <<= 4
		switch {
		case '0' <= c && c <= '9':
			val |= c - '0'
		case 'a' <= c && c <= 'f':
			val |= c - 'a' + 10
		case 'A' <= c && c <= 'F':
			val |= c - 'A' + 10
		default:
			return 0, &json.UnsupportedValueError{}
		}
	}
	return val, nil
}
