{"path": "task/workspace/data/binding/sprintf.go", "start": 1, "lines": 200, "offset": 0, "total_lines": 213, "content": "package binding

import (
	"fmt"
	"sync"
)

// NewSprintf creates a String binding that formats multiple DataItems using fmt.Sprintf.
// The format string follows fmt.Sprintf conventions. The binding updates automatically
// when any of the source DataItems change.
//
// Example:
//
//	name := binding.NewString()
//	age := binding.NewInt()
//	result := binding.NewSprintf("Name: %s, Age: %d", name, age)
//
// Since: 2.5
func NewSprintf(format string, b ...DataItem) String {
	if len(b) == 0 {
		// No bindings, just return static string
		s := NewString()
		s.Set(format)
		return s
	}

	result := &sprintfBinding{
		format:  format,
		sources: b,
		val:     "",
	}

	// Initialize with current values
	result.update()

	// Listen to all source bindings
	listener := NewDataListener(func() {
		result.update()
	})

	for _, item := range b {
		if item != nil {
			item.AddListener(listener)
		}
	}

	return result
}

// sprintfBinding combines multiple DataItems using fmt.Sprintf
type sprintfBinding struct {
	base

	format  string
	sources []DataItem
	val     string
	lock    sync.RWMutex
}

// Get returns the formatted string value
func (s *sprintfBinding) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	return s.val, nil
}

// Set is not supported for sprintf bindings (read-only)
func (s *sprintfBinding) Set(string) error {
	return fmt.Errorf("cannot set value on sprintf binding")
}

// update recalculates the formatted string from source bindings
func (s *sprintfBinding) update() {
	values := make([]interface{}, len(s.sources))

	for i, item := range s.sources {
		if item == nil {
			values[i] = nil
			continue
		}

		// Extract the actual value from the DataItem
		switch v := item.(type) {
		case String:
			if val, err := v.Get(); err == nil {
				values[i] = val
			} else {
				values[i] = ""
			}
		case Int:
			if val, err := v.Get(); err == nil {
				values[i] = val
			} else {
				values[i] = 0
			}
		case Float:
			if val, err := v.Get(); err == nil {
				values[i] = val
			} else {
				values[i] = 0.0
			}
		case Bool:
			if val, err := v.Get(); err == nil {
				values[i] = val
			} else {
				values[i] = false
			}
		case Untyped:
			if val, err := v.Get(); err == nil {
				values[i] = val
			} else {
				values[i] = nil
			}
		default:
			// For any other type, try to get as Untyped
			if untyped, ok := item.(Untyped); ok {
				if val, err := untyped.Get(); err == nil {
					values[i] = val
				} else {
					values[i] = nil
				}
			} else {
				values[i] = nil
			}
		}
	}

	newVal := fmt.Sprintf(s.format, values...)

	s.lock.Lock()
	changed := s.val != newVal
	s.val = newVal
	s.lock.Unlock()

	if changed {
		s.trigger()
	}
}

// StringToStringWithFormat creates a String binding that formats another String binding.
// The format string should contain a single %s placeholder for the source string value.
// Changes to the source String binding automatically update the formatted result.
//
// Example:
//
//	username := binding.NewString()
//	formatted := binding.StringToStringWithFormat(username, "User: %s")
//
// Since: 2.5
func StringToStringWithFormat(str String, format string) String {
	if str == nil {
		return NewString()
	}

	result := &stringFormatBinding{
		format: format,
		source: str,
		val:    "",
	}

	// Initialize with current value
	result.update()

	// Listen for changes
	str.AddListener(NewDataListener(func() {
		result.update()
	}))

	return result
}

// stringFormatBinding formats a String binding
type stringFormatBinding struct {
	base

	format string
	source String
	val    string
	lock   sync.RWMutex
}

// Get returns the formatted string value
func (s *stringFormatBinding) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	return s.val, nil
}

