// NewSprintf creates a String binding that formats multiple DataItems using fmt.Sprintf.
// The format string follows fmt.Sprintf conventions. The binding updates automatically
// when any of the source DataItems change.
//
// Example:
//
//	name := binding.NewString()
//	age := binding.NewInt()
//	result := binding.NewSprintf("Name: %s, Age: %d", name, age)
//
// Since: 2.5
func NewSprintf(format string, b ...DataItem) String {
	if len(b) == 0 {
		// No bindings, just return static string
		s := NewString()
		s.Set(format)
		return s
	}

	result := &sprintfBinding{
		format:  format,
		sources: b,
		val:     "",
	}

	// Initialize with current values
	result.update()

	// Listen to all source bindings
	listener := NewDataListener(func() {
		result.update()
	})

	for _, item := range b {
		if item != nil {
			item.AddListener(listener)
		}
	}

	return result
}

// sprintfBinding combines multiple DataItems using fmt.Sprintf
type sprintfBinding struct {
	base

	format  string
	sources []DataItem
	val     string
	lock    sync.RWMutex
}

// Get returns the formatted string value
func (s *sprintfBinding) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	return s.val, nil
}

